"""Published-reference UI with distinct identity, dates and missing metrics."""

from saia.public_signal_content_web import PUBLIC_CONTENT_SCRIPT, PUBLIC_CONTENT_STYLE

PUBLIC_STYLE = PUBLIC_CONTENT_STYLE + r'''
.badge.public{color:#3556a3;background:#eaf0ff}.public-citations{margin:12px 0}.public-citation{border:1px solid var(--line);border-radius:10px;padding:12px;margin:8px 0}.public-citation p{margin:5px 0}.public-reason{margin-top:8px}.public-reference-badge{margin-top:6px}.filters{flex-wrap:wrap}.public-review-history{margin:12px 0}.public-review-history p{font-size:12px}
'''

PUBLIC_SCRIPT = PUBLIC_CONTENT_SCRIPT + r'''
const isPublic=q=>q?.item_kind==='public_signal';
const publicYear=r=>r.source_year??(r.source_label?.match(/\b20\d{2}\b/)?.[0]||'—');
const publicLocator=r=>r.source_page!=null?`стр. ${r.source_page}`:r.source_section||'Раздел на сайте';
const publicType=r=>r.type_label||'Публичная подборка';
const publicIssued=r=>r.source_date_precision==='year'?`${publicYear(r)} · точный день не указан`:fmtDate(r.source_date);
const selectedCount=()=>state.selected.size+state.selectedPublic.size;
const itemSelected=q=>isPublic(q)?state.selectedPublic.has(q.public_signal.id):state.selected.has(q.card.candidate_id);
function selectItem(q,selected){const set=isPublic(q)?state.selectedPublic:state.selected,id=isPublic(q)?q.public_signal.id:q.card.candidate_id;selected?set.add(id):set.delete(id)}
function rebuildResultItems(){if(!state.packet)return;const published=(state.packet.result_items||[]).filter(isPublic);state.packet.result_items=[...(state.packet.queue||[]).map(q=>({...q,item_kind:'saia_candidate'})),...published]}
function publicRequested(id){return state.requests.some(r=>r.mission_id===state.mission&&r.score_run_id===state.score&&(r.public_signal_ids||[]).includes(id))}
function publicRow(q){const r=q.public_signal,selected=state.selectedPublic.has(r.id);return `<tr><td><input type="checkbox" data-public-select="${esc(r.id)}"${selected?' checked':''} ${publicSelectionAttrs(r)} aria-label="Выбрать ${esc(publicTitle(r))}"></td><td><button class="signal-name" data-public-open="${esc(r.id)}" ${publicTitleAttrs(r)}>${esc(publicTitle(r))}</button><div class="signal-sub">${esc(r.source_short_label||r.source_label)} · подборка ${esc(publicYear(r))} · ${esc(publicLocator(r))}</div><div class="row-actions"><button class="button light small" data-dispatch-public="${esc(r.id)}" aria-label="${publicRequested(r.id)?'Открыть экспертизу':'Передать на экспертизу'}: ${esc(publicTitle(r))}">${publicRequested(r.id)?'Открыть экспертизу':'На экспертизу'}</button></div></td><td data-label="Происхождение"><span class="badge public">Из публичного источника</span><div class="signal-sub">${esc(publicType(r))}</div>${publicRequested(r.id)?' <span class="badge green">На экспертизе</span>':''}</td><td data-label="Оценка кандидата"><span class="metric missing">не рассчитана</span></td><td data-label="Выпуск источника">${publicIssued(r)}</td><td data-label="Динамика публикаций"><span class="metric missing">не рассчитана</span></td></tr>`}
function publicCitations(r){return `<div class="public-citations">${(r.references||[r]).map(source=>`<div class="public-citation"><strong>${esc(source.source_label)}</strong><p class="form-note">Год подборки ${esc(publicYear(source))}${Number(publicYear(source))<2023?' · архив до 2023 года':''} · ${esc(publicType(source))}<br>${esc(publicIssued(source))} · ${esc(publicLocator(source))} · <span ${publicCategoryAttrs(source.category)}>${esc(publicCategory(source.category))}</span></p><a href="${esc(url(source.source_url)||'#')}" target="_blank" rel="noopener noreferrer">Открыть первоисточник →</a></div>`).join('')}</div>`}
function publishedReferencesControls(q){return (q.published_references||[]).length?`<div class="block"><h3>Также опубликовано во внешних подборках</h3><span class="badge public">Из публичного источника</span><p class="form-note">Совпало нормализованное название. Публикация в подборке не меняет научный балл и не подтверждает актуальный статус темы.</p>${q.published_references.map(r=>publicExplanationHtml(r)+publicCitations(r)).join('')}</div>`:''}
function publicCard(id){
  const item=all().find(q=>isPublic(q)&&q.public_signal.id===id);if(!item)return;
  const r=item.public_signal;
  openDrawer('Публичная подборка',`<span class="badge public">Из публичного источника</span>${publicContentControlMarkup}
    <h2 id="drawer-title" ${publicTitleAttrs(r)}>${esc(publicTitle(r))}</h2>
    <div class="impact-toolbar"><button class="button" id="public-dispatch">${publicRequested(id)?'Открыть экспертизу':'Передать на экспертизу'}</button></div>
    ${publicExplanationHtml(r)?`<div class="block">${publicExplanationHtml(r)}</div>`:''}
    <div class="block"><h3>Почему запись показана</h3><p>${esc(r.matching_explanation)}</p></div>
    <div class="block"><h3>Оценка и динамика <a class="help-context" href="/help#public-signals" data-horizon-help="public-signals" aria-label="Об оценке публичных сигналов">?</a></h3><div class="empty">Расчёт по источникам пока не выполнен.</div></div>
    <details class="block source-content-group"><summary>Первоисточники</summary>${publicCitations(r)}</details>
    <div class="impact-toolbar"><button class="button light small" id="public-select">${state.selectedPublic.has(id)?'Убрать из выбора':'Выбрать'}</button><a class="button ghost small" data-public-brief="/public-signals/${encodeURIComponent(id)}/brief" href="/public-signals/${encodeURIComponent(id)}/brief?lang=${publicContentLang}">Скачать карточку</a><button class="button light small" id="public-investigate">Проверить по публикациям</button></div>`);
  bindPublicContentLanguage();state.current={public_signal_id:id};
  $('public-dispatch').onclick=()=>publicRequested(id)?expertView():dispatchPublic(id);
  $('public-select').onclick=()=>{state.selectedPublic.has(id)?state.selectedPublic.delete(id):state.selectedPublic.add(id);render();publicCard(id)};
  $('public-investigate').onclick=()=>{closeDrawer();$('query').value=r.title;prepareSearch({preventDefault(){}})};
}
async function publicExpertCard(requestId,id){const dispatch=state.requests.find(r=>r.request_id===requestId),snapshot=(dispatch?.candidate_snapshot||[]).find(c=>c.public_signal_id===id);if(!snapshot)return;const r=snapshot.public_reference;openDrawer('Мнение эксперта',`<span class="badge public">Из публичного источника</span>${publicContentControlMarkup}<h2 id="drawer-title" ${publicTitleAttrs(r)}>${esc(publicTitle(r))}</h2><p class="drawer-sub">Проверьте связь с запросом, конкретность технологии, новизну на сегодняшний день и достаточность оснований в отчёте. Публикация в подборке сама по себе не является подтверждением.</p>${publicCitations(r)}<div class="block form-grid"><label>Решение<select class="field" id="public-review-decision"><option value="needs_review">Нужна дополнительная проверка</option><option value="signal_supported">Есть основания рассматривать как слабый сигнал</option><option value="noise">Шум / не относится к запросу</option><option value="possible_duplicate">Возможный дубль</option><option value="insufficient_evidence">Недостаточно данных</option></select></label><label>Имя эксперта<input class="field" id="public-review-by" maxlength="120"></label><label>Обоснование (не менее 20 символов)<textarea class="field" id="public-review-rationale" maxlength="5000"></textarea></label>${(r.references||[r]).map(row=>`<label class="source-check"><input type="checkbox" data-public-review-source="${esc(row.source_url)}"><span>${esc(row.source_label)} · ${esc(publicLocator(row))}</span></label>`).join('')}<button class="button" id="public-review-save">Сохранить мнение</button><p class="form-note" id="public-review-message">Мнение сохранится отдельно от научной оценки. Личность и квалификация эксперта не подтверждены.</p><div id="public-review-history" class="public-review-history"></div></div>`);bindPublicContentLanguage();const box=$('drawer-body'),anchor=$('public-review-save'),current=()=>$('public-review-save')===anchor&&anchor.isConnected;let operation=crypto.randomUUID(),lastContent=null;async function loadHistory(){try{const value=await request(`/public-signals/${encodeURIComponent(id)}/reviews?request_id=${encodeURIComponent(requestId)}`);if(!current())return;$('public-review-history').innerHTML=value.reviews.length?'<h3>Сохранённые мнения</h3>'+value.reviews.map(review=>`<p><strong>${esc(review.reviewed_by)}</strong> · ${fmtDate(review.created_at)}<br>${esc(review.rationale)}</p>`).join(''):''}catch{}}$('public-review-save').onclick=async()=>{const button=$('public-review-save'),message=$('public-review-message');button.disabled=true;try{const body={decision:$('public-review-decision').value,reviewed_by:$('public-review-by').value,rationale:$('public-review-rationale').value,sources:[...box.querySelectorAll('[data-public-review-source]:checked')].map(el=>el.dataset.publicReviewSource)};const content=JSON.stringify(body);if(content!==lastContent){operation=crypto.randomUUID();lastContent=content}await post(`/public-signals/${encodeURIComponent(id)}/reviews?request_id=${encodeURIComponent(requestId)}`,{...body,operation_id:operation});if(!current())return;message.textContent='Мнение сохранено. Происхождение записи и научная оценка не изменены.';loadHistory();const data=await request('/expert-requests?limit=100').catch(()=>null);if(data)state.requests=data.requests||[];}catch{if(current()){message.textContent='Не удалось сохранить мнение. Проверьте поля и повторите попытку.';button.disabled=false}}};loadHistory()}
$('origin').onchange=()=>{state.page=0;if($('origin').value==='public_signal')$('strength').value='all';render();enrichVisible()};
bindPublicContentLanguage();
'''
